// Казахский (қазақша, современная кириллица). Порядок ключей — как в ru.ts; новые ключи — в конец, своим блоком.
// Обращение к игроку — на «сен», тепло и просто. Глоссарий (одинаково по всему словарю):
//   магазин — дүкен; касса, кассир — касса, кассир; полка — сөре; склад — қойма; товар — тауар; монеты 💰 — ақша;
//   выручка — түсім; долг — қарыз; закупка — сатып алу; поставщик — жеткізуші; покупатель — сатып алушы, гость — келуші;
//   вкладки (коротко, чтобы влезли на 360 px): Закупка — Тауар, Склад — Қойма, Полки — Сөрелер, Цены — Бағалар, Зал — Зал, «Развитие» — «Даму»,
//   Магазин — Дүкен, Персонал — Ұжым (в тексте — қызметкерлер), Уголки — Бұрыштар;
//   уровни: Ларёк — Дүңгіршек, Магазинчик — Шағын дүкен, Минимаркет, Супермаркет, Универмаг — Әмбебап дүкен, Гипермаркет;
//   роли: Сменщик — Ауысымшы, Уборщик — Тазалаушы, Грузчик — Жүкші, Охранник — Күзетші, Повар — Аспаз, Курьер;
//   бабушка — әже; своя марка — өз брендің; Дед Мороз — Аяз ата, Снегурочка — Ақшақар;
//   имена героев (Эдуард, Соня, Валентина, «Гигант») — как в ru. Название игры «Магазинчик» не переводится.
// После числа слово не меняется: формы .one/.few/.many одинаковые. Суффикс к {подстановке} не клеим — фраза перестроена.
