  "arrange.intro.drag": "Сөрелерді, кассаны, автоматты, шелекті, өсімдіктерді және арзандату сөресін саусақпен сүйрет.",
  "arrange.intro.side": "Сөрені сол не оң қабырғаға жақында — ол бүйірімен бұрылып, қабырғаға жабысады. Артқы қабырғаға сөрелер тығыз тіреледі.",
