  "arrange.intro.red": "Едендегі қызыл шаршыларға болмайды: кіреберіс, қосалқы үйдің есіктері, электр қалқаны.",
  "arrange.intro.links": "Сөрелер арасындағы жасыл сызық — жақсы көршілік: нан мен сүт, ет пен көкөніс. Сатып алушы көрші сөреден де тауар ала кетеді. Қызыл — тұрмыстық химия азықтың қасында, сатып алушылар құлықсыз алады.",
