  "story.chapter": "Тарау {n}: {title}",
  "story.next": "Алға",
  "story.reward": "Сыйлық: {reward}",
  "story.goalLine": "📖 {title}: {goal}",
  "story.free": "📖 Еркін ойын: дүкенді әрі қарай дамыт",
  "story.ch1.title": "Мұра",
  "story.ch1.goal": "әженің қарызын өте ({n} 💰 қалды)",
  "story.ch1.intro1": "Сәлем! Бұл әжең. Мен апа-сіңлілеріме саяжайға кеттім, ал бұрыштағы дүңгіршегімді саған қалдырамын.",
  "story.ch1.intro2": "Дәптерімді саған хатпен жіберемін — көршілерге қарызым туралы бәрі сонда. Соларға қайтарып берші, өтінемін, — адамша.",
  "story.ch1.intro3": "О, енді сауда үстелінің артында сен тұрсың ба? Мен Валентина, әжеңнің құрбысымын. Күн сайын нанға келіп тұрамын!",
  "story.ch1.outro1": "Естідім, қарыздың бәрі қайтарылыпты! Әжең хабарласты — мақтан тұтады.",
  "story.ch1.outro2": "Жақында маған «Уют» кафесінің аспазы Марат кірген. Азық-түлікті қайдан алуды іздеп жүр…",
  "story.ch2.title": "Өзіміздікі",
  "story.ch2.goal": "2 тапсырысты орында ({n}/2) және алғашқы қызметкеріңді жалда ({staff})",
  "story.ch2.intro1": "Сәлеметсіз бе! Марат, «Уют» кафесінің аспазымын. Валентина сізде бағалар әділ деді.",
  "story.ch2.intro2": "Кейде кешке тапсырыс беріп тұрамын. Ұятқа қалдырмаңыз — залым қонаққа толы.",
  "story.ch2.outro1": "Сөзіңізде тұрасыз. Сізді барлық танысыма ұсынамын!",
  "story.ch3.title": "Бәсекелес",
  "story.ch3.goal": "минимаркетке және 4★ рейтингке дейін өс (қазір {r}★). «МегаМарт» келушілердің бір бөлігін әкетіп жатыр",
  "story.ch3.intro1": "Эдуард, «МегаМарт» директоры. Біз қарсы бетте ашыламыз.",
  "story.ch3.intro2": "Бізде қырық касса және күн сайын жеңілдік. Кеңес: дүңгіршекті әлі бір құны барда сатып жіберіңіз.",
  "story.ch3.intro3": "Оны тыңдама! Өз сатып алушыларың ешқайда кетпейді… Бірақ біразы, әрине, барып көреді.",
  "story.ch3.outro1": "Минимаркет? Рейтингі біздікінен жоғары? Мейлі-мейлі…",
  "story.ch4.title": "Тексеру",
  "story.ch4.goal": "2 тексеруден өт ({n}/2)",
  "story.ch4.intro1": "Белова, санитарлық инспекция. Сіздің үстіңізден шағым түсті.",
  "story.ch4.intro2": "Жиірек келіп тұрамын. Қоқыс, лас дәретхана, сөрелердегі ақаулы тауар, жылы тоңазытқыш — бәрін көремін.",
  "story.ch4.intro3": "Бұл Эдуард шағымданған, саған шын айтамын!",
  "story.ch4.outro1": "Үлгілі дүкен. Есепте солай жазамын.",
  "story.ch4.outro2": "Ой, мынаны қарай гөр… Ал мен оған апта бойы күңкілдеп жүрдім. Татуласу үшін оған бәліш апарайын.",
  "story.ch5.title": "Әмбебап дүкен",
  "story.ch5.goal": "әмбебап дүкенге дейін өс",
  "story.ch5.intro1": "Саяжайдан хабарласып тұрмын! Эдик саған келмекші деп естідім. Оны тыңдашы, жарай ма? Ол жақсы бала еді.",
  "story.ch5.intro2": "Қарызымды әкелдім. Нан мен сүт үшін — отыз жылғы, пайызымен. Өтінемін, алыңызшы.",
  "story.ch5.outro1": "Мен оралдым. Шынымды айтайын: ешқандай саяжайға кеткен жоқпын. Саған таңғы алтыда біреу үшін тұру керек еді.",
  "story.ch5.outro2": "Бүкіл аудан енді бізге келеді. Ал Эдуард, елестетші, көршіден дүңгіршек ашамын деп қорқытып жүр — «жалықпас үшін».",
  "story.ch5.outro3": "Ал соңғы бетті саған әзірге көрсетпеймін. Көпірдің арғы жағы әлі қараңғы… Оның да кезегі келеді.",
  "client.chef": "Марат, «Уют» кафесі",
  "client.chef.ask": "Кешке қарай {qty} × {product} керек — данасына {pay} 💰 төлеймін.",
