  "tip.promo.title": "Күн акциясы",
  "tip.promo.text": "Сатып алу бөлімінде әр тауарда «−20%» және «2=1» батырмалары бар. Күніне бір акция: тауар тез өтеді, келуші көп, бірақ үстеме аз.",
  "tip.contract.title": "Жеткізушімен келісімшарт",
  "tip.contract.text": "Бір аптаға келісімшартқа қол қой — тауарды күн сайын таңертең өздері әкеледі, 10% арзан әрі ақаусыз.",
  "tip.markdown.title": "Арзандату",
  "tip.markdown.text": "Осы түні бүлінетін тауарды арзандатуға болады: оны жарты бағаға алады, лақтырмайсың.",
  "tip.weekly.title": "Апта сынақтары",
  "tip.weekly.text": "Аптаға үш мақсат — күн сайын жинақталады. Әрқайсысы үшін сыйлықты орындаған бойда аласың.",
  "tip.fair.title": "Жәрмеңке",
  "tip.fair.text": "Айына бір рет кіреберісте жәрмеңке: үстел қоймадағы тауарды төрттен бірге қымбатырақ өзі сатады — кассаны айналып. Қоймаға тауар жинап ал!",
  "tip.cart.title": "Арба",
  "tip.cart.text": "Енді қоймадан 12 даналап тасиды. Ал «Зал» қойындысында жүкші алдымен толтыратын сөрелерді жұлдызшамен белгіле.",
  "tip.loyalty.title": "Бонус картасы",
  "tip.loyalty.text": "Карта болса, сатып алушылар 6% қымбат бағаны кешіреді — бағаны сәл көтеруге болады. Ал ештеңе алмай кеткендер рейтингті азырақ түсіреді.",
  "tip.delivery.title": "Үйге жеткізу",
  "tip.delivery.text": "Күндіз кассада телефон шырылдайды, ал төменде тапсырыс карточкасы шығады. «Қабылда» бас: тапсырысты жинайды, курьер апарып, ақшасын әкеледі, тез жеткізгені үшін — шайпұл. 15 секундта жауап бермесең — жеткізу рейтингі түсіп, сирек қоңырау шалады.",
  "tip.register2.title": "Жаңа касса",
  "tip.register2.text": "Енді касса біреу емес. Біріншісі — сенікі, ал әр жаңасына өз кассирі керек («Ұжым» қойындысы): онсыз ол жабық. Кезек бос терезеге барады.",
  "tip.oven.title": "Наубайхана",
  "tip.oven.text": "Қосалқы үйде наубайхана ашылды. «Ұжым» қойындысында наншы жалда — ол өзі нан пісіріп, сөрелерге шығарады. Нан иісі шығып тұрғанда, оны екі есе жиі алады.",
  "tip.coffee.title": "Кофехана",
  "tip.coffee.text": "Қосалқы үйде кофехана ашылды. «Ұжым» қойындысында бариста жалда, ал «Бұрыштар» қойындысында дән мен стақандарды қадағала — жаңбырда кофені жиірек алады.",
  "tip.ownerTill.title": "Касса — сенікі",
  "tip.ownerTill.text": "Бірінші кассада — сен. Кассаны немесе дүкен астындағы көшені басып, тауар өткізе аласың: саусаққа ыңғайлы. Кассирлер екінші және келесі кассаларға тұрады, ал ауысымшы («Шағын дүкен» деңгейінен) сенің кассаңа біржола тұрады — сонда басуың оны асықтырады.",
  "tip.broke.title": "Бос касса",
  "tip.broke.text": "Ақша жоқ, сөрелер бос — бұлай түсім де болмайды. Банк сатып алуға несие береді: «Даму» қойындысы → «Банк». Шоттармен бірге бөліп қайтарасың.",
  "tip.alone.title": "Жалғыз үлгермейсің",
  "tip.alone.text": "Дүкен өсті, ал касса, сөрелер мен қойма — бәрі сенің мойныңда: келушілер кетіп қалады, рейтинг өспейді. «Ұжым» қойындысында көмекшілер жалда: жүкші тауарды жайғастырады, тазалаушы жинастырады, кассир екінші кассаға тұрады.",
  "tip.nightShift.title": "Түнгі ауысым",
  "tip.nightShift.text": "Кешке тағы 45 секунд жұмыс істеуге болады: келушілер аз, бірақ бағаға таласпайды.",
