  "tour.title": "Әже дүкенді көрсетеді · {n}/{total}",
  "tour.next": "Алға",
  "tour.skip": "Өткіз",
  "tour.done": "Бастадық!",
  "tour.replay": "Әженің сабағы",
  "tour.replayNote": "Әже тағы бір рет не қайда екенін көрсетеді",
  "tour.hello": "Немерем, сәлем! Мен кетпей тұрғанда — мұнда бәрі қалай істейтінін көрсетейін. Көп уақыт алмайды!",
  "tour.top": "Жоғарыда — бүгін нешінші күн және сенде қанша ақша бар. Таңертең дайындаласың, күндіз сауда жасайсың, кешке түсімді санайсың.",
  "tour.today": "Мұнда бүгінгі ең маңыздысы: таңертең не істеу керек, ауа райы, қанша сатып алушы келеді және жалға, жарыққа қашан төлеу керек.",
  "tour.buy": "«Тауар» — тауарды осы жерден аласың. «Керегін сатып ал» бас — неге жетпейтінін өзім санап, арзан жерден аламын. Саудаласу — «Жеткізушілер» бөлімінде.",
  "tour.warehouse": "«Зал» — жоғарыда қойма: сөрелерге сыймаған қор. Таңертең ол бос орындарға өзі қойылады, ал жақында бұзылатынын арзандатқан жөн.",
  "tour.shelves": "«Зал» төменінде — сенің сөрелерің. Сөрені бас — жақсартуға, жөндеуге не сатуға болады. Жаңаларын да осында сатып аласың. Ал бағалар — «Тауар» бөлімінде.",
  "tour.extras": "«Бұрыштар» — касса жанындағы тәттілер, кофе, өз пешің, мысық. Бұл дүкен өскенде.",
  "tour.staff": "«Ұжым» — көмекшілер. Бірінші кассада әрдайым сен, ал жүкші, тазалаушы, күзетші және жаңа кассалардың кассирлері уақыт өте қалғанын өз мойнына алады.",
  "tour.store": "«Даму» — үй-жайды кеңейту, кассалар, жабдық, жарнама, шоттар және менің көршілерге қарызым. Ал жетістіктер мен баптаулар — жоғарыдағы 🏆 кубоктың астында.",
  "tour.open": "Дайын болғанда — «Дүкенді аш» бас. Сатып алушылар сөрелерден өздері алып, кассаға барады: кассаны немесе төмендегі көшені бас — тауарды өткізесің.",
  "tour.hall": "Бос сөре — оны басып, қоймадан тауар әкел. Қоқыс пен шалшықты жина, шелекті шығар. Кешке қанша тапқаныңды көресің. Сәттілік, немерем!",
  "onb.hello": "Немерем, дүңгіршек енді сенікі! Қара — келе жатыр.",
  "onb.shop": "Сатып алушы сөреден өзі алып, кассаға әкеледі.",
  "onb.serve": "Кассаны бас — сатып алуды өткіз!",
  "onb.sold": "Жарайсың! Міне, алғашқы түсім.",
  "onb.road": "Кассаға созылма — төмендегі көшені бас, ол да өткізеді!",
  "onb.bye": "Әрі қарай өзің, ал мен саяжайға. Кешке түсімді санаймыз!",
  "onb.stampTop": "Ура!",
  "onb.stamp": "Тұңғыш түсім",
  "onb.ok": "Ұқтым",
  "onb.new": "Жаңа",
  "onb.tab.buy": "Таңертең — сатып алу. «Керегін сатып ал» бас: неге жетпейтінін санап беремін.",
  "onb.tab.hall": "«Зал» — қойма мен сөрелер. Сөрені бас: жақсарту, жөндеу не сату.",
  "onb.tab.staff": "Жалғыз қиын ба? «Ұжым» бөлімінде көмекші жалдауға болады.",
  "onb.tab.grow": "«Даму» — дүкенді кеңейту, кассалар, жарнама және менің көршілерге қарызым.",
  "onb.tab.extras": "«Бұрыштар» — касса жанындағы тәттілер, кофе, өз пешің және мысық.",
