  "tut.summary": "Міне, күн қорытындысы: қанша тапқаның және қанша келуші болды. «Келесі күн» бас — таңертең сатып аламыз.",
  "tut.buyTab": "Таңертең — сатып алу. «Тауар» бөлімін аш.",
