  "tut.week.product": "Жаңалық: {name}. Жеткізушілерде бар, бізде әзірге жоқ — «Тауар» бөлімінен аздап ал, сатып алушылар сұрайды!",
  "tut.week.price": "«Тауар» бөліміндегі бағаларға қара: басқа жеткізушіде арзанырақ болады.",
  "tut.week.event": "Енді залда әуре болып тұрады: көгершін, тышқан, су ағу. Көрсең — бас, шешеміз!",
  "tut.week.staff": "Жалғыз шаршайсың ба? «Ұжым» бөлімінде жүкші жалда — ол тауарды сөрелерге өзі жайғастырады.",
  "tut.week.grow": "Үлкенірек үй-жайға жина: «Даму» бөлімінде біріншісі — {cost} 💰. Онда сөре де, келуші де көп.",
  "tut.week.gift": "Сөре басында бір апта — жарайсың! Саяжайдан сәлемдеме жібердім: алма мен картоп қоймада тұр.",
