  "upgrade.autoOrder": "Автотапсырыс",
  "upgrade.autoOrder.desc": "Көмекші: әр таңертең лимит шегінде күнге қажеттіні өзі сатып алады, ал күндіз таусылған тауарды жеткізеді",
  "upgrade.bargain": "«Арзан» сөре",
  "upgrade.bargain.desc": "Кіреберісте «−50%» белгісі бар сөре: түнде бұзылатын тауар сонда жарты бағаға кетеді. Сатып алушылар одан тізімнен тыс алады. Үлкенірек сөре — «Жабдық» бөлімінде",
