  "staffEvent.wedding.text": "«Қожайын, әпкемнің тойы бар! Ертең жібересіз бе? Кейін өтеймін, шын сөзім». Жіберсең — шабыттанып оралады да, бірнеше күн жылдамырақ істейді. Бас тартсаң — ренжиді.",
