  "tale.need.money": "{n} 💰 керек",
  "tale.need.product": "қойма мен сөрелерде {n} дана керек",
  "tale.anya.name": "Студент Аня",
  "tale.anya.0.text": "«Сәлем! Мен Аня, экономистке оқимын. Шәкіртақым кешігіп жатыр… Тауарды сөрелерге қоюға көмектессем, маған бір бөлке нан бересің бе?»",
  "tale.anya.0.0": "Әрине, нанды ал",
  "tale.anya.0.1": "Кешір, бүгін емес",
  "tale.anya.1.text": "Аня тағы келді: «Сол жолы мені құтқардың! Жақында сессия, ал оқулық 300 тұрады. Қарызға бересің бе? Алғашқы жалақымнан қайтарамын, шын айтам».",
  "tale.anya.1.0": "Мә, 300 💰",
  "tale.anya.1.1": "Бере алмаймын",
  "tale.anya.2.text": "Аня жайнап тұр: барлық емтиханды «өте жақсыға» тапсырды! Қарызын екі есе қайтарды — 600 💰 — және бүкіл тобын ертіп келді: «Мұнда қаладағы ең мейірімді дүкен иесі!»",
  "tale.anya.2.0": "Рақмет, Аня!",
  "tale.anya.3.text": "Аня жаңалығымен бөлісуге кірді: сессия тапсырылды! Оқулықты кітапханадан алыпты. Бірнеше топтасын ертіп келді.",
  "tale.anya.3.0": "Қуанып тұрмын!",
  "tale.anya.4.text": "Аня диплом алып, көршідегі банкке жұмысқа тұрды. «Сен туралы барлық әріптестеріме айттым — енді түскі асты тек сенен алады!»",
  "tale.anya.4.0": "Тамаша!",
  "tale.wedding.name": "Күйеу жігіт Тимофей",
  "tale.wedding.0.text": "Жігіт қолындағы сақиналы қорапшаны уқалап тұр: «Мен Тимофеймін. Катя екеуміз сенің кезегіңде танысқанбыз! Оған дәл есік алдында ұсыныс жасағым келеді. Витринаны безендіруге көмектесесің бе? Шарлар, гирлянда — шамамен 200».",
  "tale.wedding.0.0": "Безендірейік! (−200 💰)",
  "tale.wedding.0.1": "Бұл дүкен ғой, АХАЖ емес",
  "tale.wedding.1.text": "Катя «иә» деді! Ауданның жартысы витрина алдында қол соқты. Тимофей: «Той 5 күннен кейін. Дастарқан мен бутербродқа 30 бөлке нан керек — екі есе төлейміз!»",
  "tale.wedding.1.0": "Келістік!",
  "tale.wedding.1.1": "Шамамыз жетпейді, кешір",
  "tale.wedding.2.text": "Той күні! Костюм киген Тимофей тапсырысын алуға келді: 30 бөлке нан.",
  "tale.wedding.2.0": "Міне, тапсырысың!",
  "tale.wedding.2.1": "Кешір, үлгермедік…",
  "tale.wedding.3.text": "Тимофей мен Катя бал айынан оралды: «Енді тек саған келеміз. Тойдағы барлық қонаққа да айттық!»",
  "tale.wedding.3.0": "Құтты болсын!",
  "tale.busker.name": "Музыкант Гоша",
  "tale.busker.0.text": "Есік алдында гитарасы бар жігіт: «Мен Гошамын. Дүкеніңнің жанында ойнасам бола ма? Адамдарға көңілді — саған сатып алушы».",
  "tale.busker.0.0": "Ойна!",
  "tale.busker.0.1": "Шу керек емес",
  "tale.busker.1.text": "Гошаның сенің есігіңде ән айтқан видеосы миллион қаралым жинады! Бір блогер тура залда ролик түсіргісі келеді.",
  "tale.busker.1.0": "Түсір!",
  "tale.busker.1.1": "Жоқ, жұмысқа кедергі",
  "tale.busker.2.text": "Гоша топ құрып, алғашқы концертіне шақырады. Демеуші керек: 1000 💰 — сонда сенің дүкенің қаладағы барлық афишада болады.",
  "tale.busker.2.0": "Демеуші болу (−1000 💰)",
  "tale.busker.2.1": "Сәттілік, Гоша!",
