  "nightGuest.taxi.0": "Таң атқанша ауысым… Су болса ғой!",
  "nightGuest.taxi.1": "Бес минут үзіліс — сосын тағы рульге",
  "nightGuest.student.0": "Сессия! Тұшпара мен шырын керек",
  "nightGuest.student.1": "Курстық жұмыс өзі жазылмайды ғой…",
  "nightGuest.doctor.0": "Кезекшіліктен жаңа шықтым. Пайдалы бірдеңе бар ма?",
  "nightGuest.doctor.1": "Бір тәулік аяқ үстінде — алма мен шырын",
  "nightGuest.guard.0": "Түнгі айналым, ал қарын аш",
  "nightGuest.guard.1": "Қарсыдағы қойманы күземін. Нан болса ғой",
  "nightGuest.musician.0": "Концерт бітті, бірақ күш әлі көп!",
  "nightGuest.musician.1": "Саған бірдеңе ойнап берейін бе?",
  "nightGuest.insomniac.0": "Ұйқым келмейді… жылы сүт болса ғой",
  "nightGuest.insomniac.1": "Біздің кезімізде дүкендер түнде істемейтін!",
  "nightGuest.lovers.0": "Түнгі сағат екіде гүл — бар ма?",
  "nightGuest.lovers.1": "Тсс… бұл оған тосынсый",
  "nightGuest.vampire.0": "Қызанақ шырыны бар ма? Тек қызанақ…",
  "nightGuest.vampire.1": "Жарығың тым жарқын екен… мейлі",
