  "nightStory.studentDebt.text": "«Стипендия тек үш күннен кейін, ал қазір қарным ашып тұр. {item} қарызға бересің бе? Шын айтам, екі есе қайтарамын!»",
  "nightStory.studentDebt.note": "Әдетте қайтарады — әрі достарын ертіп келеді. Бірақ әрқашан емес.",
  "nightStory.studentDebt.yes": "Ас болсын",
  "nightStory.studentDebt.no": "Кешір, қарызға бермейміз",
