  "nightStory.taxiTea.text": "«Сенде он минуттай жылынып алайын ба? Ал мен жолаушыларға дүкенің туралы айтып берем — тәулік бойы ашық, мейірімді»",
  "nightStory.taxiTea.note": "Ертең келушілер 6% көп.",
  "nightStory.taxiTea.yes": "Әрине, жылын",
  "nightStory.taxiTea.no": "Бізде күту залы емес",
