  "nightStory.sleepyDoctor.text": "Тәуліктік кезекшіліктен кейін дәрігер кассаның қасына отырды — да, себетін қолына ұстаған күйі ұйықтап қалды.",
  "nightStory.sleepyDoctor.note": "Ұйқысы қанса — көп сатып алып, әріптестеріне айтады.",
