  "decor.holidayEarn": "🎁 ашықхатқа",
  "decor.holidayNote": "Мерекелік зат: оны мереке ашықхаттары сыйлайды — {when}. Сатып алуға болмайды, тек жинауға болады.",
  "decor.holidayWhen.newyear": "желтоқсанда",
  "decor.holidayWhen.feb23": "23 ақпанға",
  "decor.holidayWhen.march8": "8 наурызға",
  "decor.packNote": "Тек «{pack}» жиынтығымен сатылады: {items}. Бір рет сатып алынады да, мәңгі қалады.",
  "live.newyear.card.1": "Бірінші желтоқсан! Дүкен ақырындап сәнделіп жатыр — қыстың алғашқы күні құтты болсын!",
  "live.newyear.card.2": "Сыртта қар иісі, ал залда — мандарин иісі. Күнің сәтті өтсін!",
  "live.newyear.card.3": "Бүгін касса жиірек сыңғырласын, ал жүрегің жылы болсын.",
  "live.newyear.card.4": "Сатып алушылар аяздан алма бет болып кіреді — әрқайсысына күліп қара.",
  "live.newyear.card.5": "Гирлянда іліп, шәйнек қоятын кез келді.",
  "live.newyear.card.6": "Аяқ астында қар сықырлайды — демек, қыс нағыз. Күнің жылы өтсін!",
  "live.newyear.card.7": "Желтоқсанның бір аптасы артта! Күн сайын кіріп тұрғаның үшін рақмет.",
  "live.newyear.card.8": "Кішкентай тілек тіле — Жаңа жылға дейін орындалып үлгереді.",
  "live.newyear.card.9": "Біреулер сыйлық таңдап жүр. Саған да соқсын!",
  "live.newyear.card.10": "Бір кесе какао мен витринаның жылы жарығы — міне, жайлылық.",
  "live.newyear.card.11": "Бүгін бірде-бір йогурттың мерзімі өтпесін!",
  "live.newyear.card.12": "Қысқы кеште витрина ерекше жарқырайды.",
  "live.newyear.card.13": "Әже айтады: желтоқсанда тіпті нанның өзі мереке иісін береді.",
  "live.newyear.card.14": "Әйнектерде — аяз өрнектері. Әдемі, иә?",
  "live.newyear.card.15": "Желтоқсанның екі аптасы артта. Бізбен біргесің, рақмет!",
  "live.newyear.card.16": "Жаңа жылға дейінгі жолдың жартысы! Мә, кішкентай сыйлық.",
  "live.newyear.card.17": "Бүгін сатып алушылар мейірімді, кезектер қысқа болсын.",
  "live.newyear.card.18": "Мандарин, шырша, гирлянда — мереке есік қағып тұр.",
  "live.newyear.card.19": "Мысық та Жаңа жылды күтіп жүр. Әсіресе мерекелік кешкі астағы балықты.",
  "live.newyear.card.20": "Қыс күндері қысқа — жақсы сәттер ұзақ болсын.",
  "live.newyear.card.21": "Жылдың ең ұзақ түні. Енді тек жарығырақ болады!",
  "live.newyear.card.22": "Үш апта артта. Мерекеге дейін қол созым жер!",
  "live.newyear.card.23": "Бүгін кем дегенде бір жағымды тосын жағдай болсын.",
  "live.newyear.card.24": "Шыршаның астына сыйлықтар жинала бастады. Ал саған — ашықхат!",
  "live.newyear.card.25": "Жаңа жылға бір апта қалды! Ғажайыптардың дәл уақыты.",
  "live.newyear.card.26": "Біреу есік алдында аққала жасап жатыр. Қыс нағыз қызған шағында!",
  "live.newyear.card.27": "Жаңа жылда дүкенің бұрынғыдан да жайлы болсын.",
  "live.newyear.card.28": "Аз ғана қалды. Мереке алдындағы әбігерде өзіңді күт!",
  "live.newyear.card.29": "Салат, мандарин, гирлянда — және бір тамшы сиқыр.",
  "live.newyear.card.30": "Ертең — жылдың соңғы күні. Қаншама іс бітіргеніңді есіңе ал!",
  "live.newyear.card.31": "Жаңа жылың құтты болсын! Желтоқсан бойы бізбен бірге болғаның үшін рақмет. Жыл жылы болсын!",
  "live.feb23.card.1": "Отан қорғаушы күні құтты болсын! Қасыңда әрдайым қолдайтын жандар болсын.",
  "live.feb23.card.2": "Мықты денсаулық, жан тыныштығы және сенімді иық!",
  "live.feb23.card.3": "Мерекең құтты болсын! Батылдық пен мейірім әрдайым қатар жүрсін.",
  "live.march8.card.1": "Көктем табалдырықта! Әр күнің жылы әрі жарық болсын.",
  "live.march8.card.2": "Мимозадан көктем иісі шығады. Көңіл күйің де сондай шуақты болсын!",
  "live.march8.card.3": "8 наурыз құтты болсын! Айналаңда гүл, күлкі және жылы сөз көп болсын.",
  "ads.guests": "Келуші қосады: күніне ≈{n}",
  "news.kiosks": "🖥 Өзіне-өзі қызмет ету кассалары: себеті шағын сатып алушылар тауарды өздері өткізеді — «Даму» → «Өзіне-өзі қызмет ету кассалары».",
  "news.relief": "🧑‍💼 Ауысымшы («Шағын дүкен» ғимаратынан бастап) күні бойы сенің кассаңа тұрады — сен басқа істерге боссың. «Ұжым».",
  "news.restock": "📦 «Керегін сатып алу» — бір басу: тауар бірден сөрелерге де, қоймаға да түседі.",
  "news.housewarming": "🏠 Қоныс той: көшкеннен кейінгі алғашқы шот — әлі ескі жалдау ақысымен.",
  "news.branch": "🏬 Филиал: «Әмбебап дүкен» деңгейінде «Гигант» дүкенін жеңген соң, оның ғимаратын сатып алуға болады — екінші дүкен әр түні өзі табыс әкеледі. «Даму» → «Филиал».",
  "news.goal": "🎯 Жоғарыда — жолағы бар бір басты мақсат: бас, сонда әрі қарай не істеу керегін айтады. Күн қорытындысында — ертең не күтіп тұрғаны. Ал блоктарды жиғанда мәзір енді секірмейді.",
  "news.newyear": "🎄 Желтоқсанда — жаңажылдық күнтізбе: күн сайын сыйлығы бар ашықхат, ал қонаққа Аяз ата келеді.",
  "news.prices": "🏷 Бағаларды түзеттік: кіреберіс, дәретхана, LED-жарық, электронды баға белгілері мен киоскілер арзандады; адалдық картасы, камералар мен қымбат жарнама қымбаттады; түнгі ауысым қарапайымдау. Сатып алғаның сақталады.",
