  "store.l6": "Гипермаркет",
  "hyper.title": "Гипермаркетке көшу",
  "hyper.lock.giant": "Жолдың арғы бетіндегі «Гигант» ғимараты әзірге соның қолында. «Гигант» дүкенін жең, сол жерде филиал аш — сонда бас дүкенді соған көшіре аласың.",
  "hyper.lock.branch": "Алдымен «Гигант» ғимаратында филиал аш (төменде, «Филиал») — содан кейін толықтай сонда көше аласың.",
  "hyper.offer": "Бас дүкен «Гигант» ғимаратына көшеді: үлкен зал, сөрелерге {slots} орын, {wh} орындық қойма, келушілер ×{g}. Жалдау ақысы — айына {rent} 💰, алғашқы шот — әлі ескі бағамен.",
  "hyper.branch": "Ескі дүкен жабылмайды: ол «{name}» филиалы болады. Басқарушы командасымен сонда ауысады, филиалдың барлық жақсартулары сақталады, табыс — бұрынғыдай.",
