  "gift.treat.7": "үлкен балды торт",
  "letter.grandma.1": "Немерем, қалайсың? Түскі асты ұмытпайсың ба? Ұсақ-түйек шығынға аздап салып жібердім — өзіңе көкнәр тоқаш сатып ал.",
  "letter.grandma.2": "Кеше кеш бойы кішкентай кезіңде сөренің артына тығылғаның есіме түсті. Енді өзің дүкен иесісің! Мақтанамын. Саған аздап салып жібердім.",
  "letter.grandma.3": "Үшінші қабаттағы көрші әйел сенің наныңды мақтады. Біздің ауылдағыдай жұмсақ дейді. Дүкен шаруасына ал.",
  "letter.grandma.4": "Шырақ жарығымен жазып отырмын — бізде тағы жарық өшті. Бағаны көтере берме, жақсы адамдар ұмытпайды. Мә, аздап, қарсы болма.",
  "letter.grandma.5": "Саған шұлық тоқыдым, демалыста әкелемін. Әзірге — конвертте азын-аулақ ақша, касса көңілдірек сыңғырласын.",
  "letter.grandma.6": "Теледидардан жаңбыр болады дегенді көрдім. Кіреберіске қолшатыр қой! Мә, саған әйтеуір керек болар.",
  "letter.grandma.7": "Атаң айтушы еді: «Дүкен күн сайын келетіндердің арқасында тұрады». Сен солар үшін тырыс, мен — сен үшін. Сүйемін.",
  "letter.grandma.8": "Бәліштер бұрын-соңды болмағандай болып шықты! Өкінішке қарай, поштамен жібере алмайсың. Жіберуге болатынын жіберіп отырмын — шайға бірдеңе сатып ал.",
  "letter.valya.1": "Сәлем, көрші! Кеше кешке сенде жарық түн ортасына дейін жанып тұрғанын көрдім. Тым шаршап қалма. Бірдеңе болса — қабырғаны қақ.",
  "letter.valya.2": "Базарда естідім: сүт жақында қымбаттайды. Алдын ала біліп жүр деп, көрші ретінде айтып отырмын.",
  "letter.valya.3": "Мысығымның тәбеті тағы жоғалды, ал сенің балығыңды бас алмай жейді! Сондықтан мені қонаққа күт — балыққа келемін.",
  "letter.valya.4": "Кеше кезегің бұрышқа дейін созылды. Қатты қуандым! Тек екінші кассир керек сияқты, ә?",
  "letter.valya.5": "Кассаның жанындағы гүлдер — керемет. Әпкеме сатып алдым, ол әлі күнге базардан деп ойлайды. Сені сатпаймын!",
  "letter.valya.6": "Таңертең сенің қолың тимейді, сондықтан хат жазып қалдырдым. Маған жаңа піскен батон қалдырғаның үшін рақмет. Ұсақ нәрсе, бірақ жағымды.",
  "letter.sonya.1": "Әке, көркемсурет мектебіндегі портфолиоға біздің дүкенді салдым. Мысық сенен маңыздырақ шықты. Ренжіме.",
  "letter.sonya.2": "Әке, қоғамтанудан шағын бизнес туралы эссе берді. Сенен сұхбат алсам бола ма? Тек байыппен жауап бер.",
  "letter.sonya.3": "Әке, сенбіде кассада тұрсам бола ма? Мен сенен жылдам санаймын, тексерілген.",
  "letter.sonya.4": "Әке, дүкенге әлеуметтік желіде парақша аштым. Қазірдің өзінде қырық жазылушы. Алғыстың қажеті жоқ.",
  "letter.sonya.5": "Әке, тағы кешігесің бе? Кешкі ас тоңазытқышта, үстіне жазып қойдым — әйтпесе әже жеп қояды.",
  "letter.sonya.6": "Әке, кәсіптік бағдар сабағында кім болғың келеді деп сұрады. Әзірге білмеймін, бірақ қызықсыз үлкен адам болмаймын дедім. Сен есепке кірмейсің.",
  "letter.regular.1": "Дүкен иесі, рақмет! {item} — «Гигант» дүкеніндегіден жақсы, шын сөзім. Біліп жүр деп жазып отырмын: мен сенің сатып алушыңмын.",
  "letter.regular.2": "Кеше соқтым, бірақ сен бос емес едің. Айтайын дегенім: сенің дүкеніңде үйдегідей. Ертең тағы соғамын.",
  "letter.regular.3": "Немереме сенің шағын дүкеніңді айтып бердім — енді ол да сатушы болғысы келеді. Абыройыңды түсірме!",
  "letter.regular.4": "Есіктің астына хат қалдырып барамын: сенде {item} — менің әлсіз тұсым. Тек бағасын көтерме, келістік пе?",
  "letter.regular.5": "Басқа аудандағы әпкемде болдым — онда мұндай дүкен жоқ. Сенің кассаңды сағындым, елестетесің бе?",
  "letter.regular.6": "Кешігіп жатқанымда маған сақтап қойғаның үшін рақмет — {item}. Мұндай нәрсе ұмытылмайды.",
  "letter.regular.7": "Дүкен иесі, залың енді сондай жарық әрі таза! Кіру жағымды. Әжеңе сәлем айт.",
  "letter.regular.8": "Жай ғана ашықхат жазып отырмын. Сенің дүкенің бар кезде біздің аудан жақсы.",
