  "hood.title": "Ауданды көркейту",
  "hood.note": "Дүкен өсті — енді айналаны да әдемілейтін кез. Сатып алғанның бәрі көшеде мәңгі қалады және дүкенге аздап көмектеседі.",
  "hood.spent": "Ауданға салынды: {n} 💰 · келушілер +{g}%",
  "hood.lock.level": "🔒 Ашылады: «{name}» ғимаратында",
  "hood.lock.rest": "🔒 Алдымен ауданның қалғанын көркейт",
  "hood.needNoDebt": "Алдымен қарызыңды өте.",
  "hood.done": "✓ Дайын",
  "hood.effect.guests": "келуші +{n}%",
  "hood.effect.rating": "рейтинг +{n}",
  "hood.effect.tips": "тұрақтылар шайпұлы +{n}%",
  "hood.bought": "Аудан көркейіп келеді!",
  "hood.boughtText": "«{name}» — көшеде тұр. Кешке де кіріп қара!",
  "hood.lamps": "Жаңа шамдар",
  "hood.lamps.desc": "Арғы тротуар бойындағы екі плафонды шойын шамдар. Кешке көше жарық әрі жайлы.",
  "hood.beds": "Гүл құмыралары",
  "hood.beds.desc": "Тротуар бойындағы тас құмыралар: жазда гүл, қыста шырша бұтақтары.",
  "hood.bikes": "Велотұрақ",
  "hood.bikes.desc": "Кіреберістегі велосипед тұғырлары — велосипедпен кіру оңайырақ.",
  "hood.bus": "Аялдама",
  "hood.bus.desc": "Жалаң бағананың орнына — шыны шатырлы, орындықты аялдама. Автобус күткендер саған кіреді.",
  "hood.mural": "Граффити",
  "hood.mural.desc": "Суретшілер саябақ жанындағы қабырғаны безендіреді: күн, гүлдер және бауырсақ ұстаған әже. Тұрақтылар ауданын мақтан етеді.",
  "hood.benches": "Орындықты саябақ",
  "hood.benches.desc": "Жол арғы бетіндегі плиткалы алаң, орындықтар мен бұталар — сатып алғанмен отыратын жер бар.",
  "hood.fir": "Алаңдағы шырша",
  "hood.fir.desc": "Саябақтағы үлкен шырша. Қыста оны безендіреді: ойыншықтар, гирлянда және жұлдыз.",
  "hood.fountain": "Тоған фонтаны",
  "hood.fountain.desc": "Саябақтағы тоған жағасындағы фонтан: жазда онда бүкіл аудан серуендейді.",
  "hood.playground": "Ойын алаңы",
  "hood.playground.desc": "Саябақта сырғанақ, әткеншек және құм салғыш. Балалы аналар — жиі келетін сатып алушылар.",
  "hood.facades": "Көршілер қасбеті",
  "hood.facades.desc": "Көрші үйлерге — терезе астына гүл жәшіктері мен жалаушалар. Көше ашықхаттағыдай.",
  "hood.fair": "Жәрмеңке",
  "hood.fair.desc": "Саябақта үш әсем дүңгіршек: бал, алма және бәліш. Жұрт көшеге ағылады.",
  "hood.statue": "Әжеге ескерткіш",
  "hood.statue.desc": "Алаңдағы бауырсақ ұстаған қола әже. «Сауданың негізін қалаушыға — алғысы шексіз аудандан».",
  "hood.statue.plaque": "Әжеге",
  "ach.hood_first": "Аудан демеушісі",
  "ach.hood_first.desc": "Ауданды көркейтудің алғашқысын сатып ал",
  "ach.hood_half": "Үздік көше",
  "ach.hood_half.desc": "Ауданды көркейтудің алтауын сатып ал",
  "ach.hood_all": "Құрметті тұрғын",
  "ach.hood_all.desc": "Әжеге ескерткіш орнат",
  "news.hood": "🌷 Ауданды көркейту: шамдар, фонтан, саябақ, тіпті әжеге ескерткіш — бәрі көшеде көрінеді. «Даму».",
  "moment.coin": "Тиын! 👆",
  "moment.tipjar": "Шайпұл! 👆",
