  "career.leave.1": "«Өзімнің шағын наубайханамды ашамын. Бәрін сен үйреттің — рақмет!»",
  "career.leave.2": "«Әрі қарай оқуға барамын — көптен армандап жүрмін. Қонаққа келіп тұрамын!»",
  "career.leave.3": "«Басқа қалаға туыстарыма көшемін. Біздің дүкенді сағынамын».",
  "career.leave.4": "«Лайықты демалысқа шығатын кез келді. Сөре артында қанша жыл — жетер, енді немерелер!»",
  "career.left.note": "Дүкендегі ауысым: {days}. Жақсы қоштасасыңдар — қарызсыз, өкпесіз, хат жазуға уәде береді.",
