  "career.head": "💼 Филиалды басқарады: {name} ({day}-күннен бері): табысқа +{p}%",
  "career.nextBest": "🏅 Ай қызметкері — {n} күннен соң",
  "letter.staff.1": "Наубайхана ашылды! Әзірге шағын, үш үстелдік. Нан пісіріп жүріп, сенімен таң атқанша көлік түсіргенімізді еске аламын. Кел — тегін сыйлаймын. Біздің дүкенде болған бәрі үшін рақмет!",
  "letter.staff.2": "Оқып жүрмін! Қиын, бірақ қызық. Курстастарыма біздің дүкен туралы айтамын — осындай жақсы дүкен болады дегенге сенбейді. Жібергенің үшін рақмет.",
  "letter.staff.3": "Жаңа жерге орналастық. Мұнда дүкен бар, бірақ ондай емес — мысық та, әженің бәліштері де жоқ. Барлығына сәлем айт, мысықтың құлағының артын қасып қой.",
  "letter.staff.4": "Демалып жүрмін, қызанақ отырғызамын. Немерелерге біздің дүкен туралы айтамын — қанша ауысым, әзіл ме! Егер мүлде қолың тимей қалса — шақыр, жастығымды еске аламын.",
  "lazy.offTitle": "Байланыс үзілді",
  "lazy.offText": "Ойынның бір бөлігі жүктелмеді — қайта іске қосамыз, бәрі сақталған.",
  "product.jam": "Тосап «Әжеден»",
  "product.pickles": "Өзіміз тұздаған тұздамалар",
