  "product.kvass": "Үй квасы",
  "lines.jam": "Әженің тосабы",
  "lines.pickles": "Тұздамалар",
  "lines.pelmeni": "Қолдан түйген тұшпара",
  "lines.kvass": "Бөшкедегі квас",
  "lines.jam.desc": "Көрші әже кешке қоймадағы алмадан қайнатады — тіпті бұзылайын деп тұрғандарынан да.",
  "lines.pickles.desc": "Қияр мен қызанақ фермерден, тұздығы өзіміздікі. Күзде өнім мол: көбірек әрі арзанырақ тұздайды, қыста ықыласпен алады.",
  "lines.pelmeni.desc": "Аспаз ауысымнан кейін қоймадағы еттен түйеді. Тек ол жұмыс істеген күндері ғана.",
  "lines.kvass.desc": "Кешегі наннан жасалған квас — көктем мен жазда, кіреберісте сары бөшке. Жазда қолма-қол өтеді.",
  "lines.title": "Өз брендің сөрелерде",
  "lines.note": "Түнде, жабылғаннан кейін жасайды — таңертең банкалар сөреде тұрады. Жеткізушілерде мұндай жоқ: өзіңдікін ықыласпен әрі қымбатырақ алады. Әр саты — көбірек қор және жоғарырақ сұраныс.",
  "lines.fame": "⭐ Бренд даңқы: {n} — өзіңдікінің бәрін (пісірмелерді де) {p}% жиірек алады.",
