  // Питомцы за звёзды (game/pets.ts) и улица друзей (game/street.ts).
  "pets.title": "Жануарлар",
  "pets.note": "Жай көңіл үшін: үй жануарлары ақша да, келуші де әкелмейді — жай ғана залда тұрады. Бір уақытта біреуі ғана, басқасын кез келген кезде шақыра аласың.",
  "pets.here": "залда",
  "pets.rename": "Аты",
  "pets.away": "Үйге",
  "pets.call": "Шақыр",
  "pets.cosmetic": "Тек сән үшін: түсім мен келушілерге әсер етпейді. Сатып алсаң — мәңгі сенікі, тіпті «Жаңа ойын» басқаннан кейін де.",
  "pets.welcome": "Үйге қош келдің! Атын кім қоямыз?",
  "pets.nameAsk": "Жануар аты",
  "pets.nameOk": "Дайын",
  "pets.tap": "{name} ❤",
  "pets.record": "{name} рекордқа қуанып жатыр! 🎉",
  "pets.parrot.words": "Сәлем!,Нан ал!,Касса!,Ура!,Жарайсың!,Рахмет!,Жеңілдік!",
  "pets.parrot.title": "Тотықұс",
  "pets.parrot.name": "Тотыш",
  "pets.parrot.about": "Касса жанындағы таяқшада отыратын сөзуар: анда-санда бір сөзді айқайлап жібереді.",
  "pets.parrot.life": "Таңертең амандасады, рекорд күні қанат қағады, түнде басын қауырсынына тығады.",
  "pets.greet.parrot": "{name}: «Сәл-лем! Ашық-пыз!»",
  "pets.hamster.title": "Хомяк",
  "pets.hamster.name": "Үлпек",
  "pets.hamster.about": "Касса жанындағы дөңгелегі бар тор: дүкен ашық тұрғанда тынбай жүгіреді.",
  "pets.hamster.life": "Күнбағыс дәнімен демалады, рекордқа қуанады, түнде түйіліп ұйықтайды.",
  "pets.greet.hamster": "{name} дөңгелегін айналдырып та жатыр!",
  "pets.turtle.title": "Тасбақа",
  "pets.turtle.name": "Тортилла",
  "pets.turtle.about": "Қабырға жанындағы асықпайтын көрші. Түнгі ауысымда залды баяу аралайды.",
  "pets.turtle.life": "Таңертең амандасу үшін басын шығарады, дүкен жабық кезде сауытында ұйықтайды.",
  "pets.greet.turtle": "{name} баяу бас изейді: қайырлы таң",
  "pets.bunny.title": "Қоян",
  "pets.bunny.name": "Түймеш",
  "pets.bunny.about": "Бұрыштағы сабан кілемшедегі үлпілдек: мұрнын қимылдатып, секіріп қояды.",
  "pets.bunny.life": "Секіріп амандасады, рекордта қуанғаннан секіреді, түнде «бөлке» болып ұйықтайды.",
  "pets.greet.bunny": "{name} секіреді: қайырлы таң!",
  "pets.corgi.title": "Корги",
  "pets.corgi.name": "Бауырсақ",
  "pets.corgi.about": "Кіреберістегі төсеніште қалғиды да, әр келушіге бөксесін бұлғаңдатады.",
  "pets.corgi.life": "Таңертең иесін қарсы алады, рекорд күні тоқтамай бұлғаңдайды, түнде қатты ұйықтайды.",
  "pets.greet.corgi": "{name} бұлғаңдайды: иесі келді!",
  "pets.raccoon.title": "Енот",
  "pets.raccoon.name": "Шапшаң",
  "pets.raccoon.about": "Қойма есігінің жанында тұрады: бірде сығалайды, бірде тығылады. Түнде мүлде тығылмайды.",
  "pets.raccoon.life": "Таңертең және рекордта табанын бұлғайды, дүкен жабық кезде қорапта ұйықтайды.",
  "pets.greet.raccoon": "{name} есік артынан табанын бұлғайды",
